-- ---------------------------------------------------------------------------
-- Hand-written constraints (Prisma's schema language cannot express them).
-- ---------------------------------------------------------------------------

-- consent_decisions: health data decisions name a source and scopes; the
-- other consent types are switches without either.
ALTER TABLE "consent_decisions"
    DROP CONSTRAINT "consent_decisions_source_id_known",
    DROP CONSTRAINT "consent_decisions_scopes_match_state",
    ADD CONSTRAINT "consent_decisions_source_matches_type" CHECK (
        ("consent_type" = 'health_data' AND "source_id" IS NOT NULL AND "source_id" IN ('apple_health', 'health_connect'))
        OR ("consent_type" <> 'health_data' AND "source_id" IS NULL)
    ),
    ADD CONSTRAINT "consent_decisions_scopes_match_state" CHECK (
        ("consent_type" = 'health_data' AND "state" = 'granted' AND cardinality("scopes") > 0
            AND "scopes" <@ ARRAY['sleep_duration', 'steps', 'heart_rate', 'resting_heart_rate']::text[])
        OR ("state" = 'revoked' AND cardinality("scopes") = 0)
        OR ("consent_type" <> 'health_data' AND cardinality("scopes") = 0)
    );

-- user_credentials ----------------------------------------------------------
ALTER TABLE "user_credentials"
    ADD CONSTRAINT "user_credentials_email_normalized" CHECK ("email" = lower(btrim("email"))),
    ADD CONSTRAINT "user_credentials_email_format" CHECK ("email" ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
    ADD CONSTRAINT "user_credentials_password_hash_argon2id" CHECK ("password_hash" LIKE '$argon2id$%');

-- auth_sessions -------------------------------------------------------------
ALTER TABLE "auth_sessions"
    ADD CONSTRAINT "auth_sessions_revocation_complete" CHECK (("revoked_at_utc" IS NULL) = ("revoked_reason" IS NULL)),
    ADD CONSTRAINT "auth_sessions_expiry_after_creation" CHECK ("expires_at_utc" > "created_at_utc");

-- auth_tokens: only hashes are stored, and the only permitted change is
-- marking the refresh token as used.
ALTER TABLE "auth_tokens"
    ADD CONSTRAINT "auth_tokens_access_token_hash_format" CHECK ("access_token_hash" ~ '^[0-9a-f]{64}$'),
    ADD CONSTRAINT "auth_tokens_refresh_token_hash_format" CHECK ("refresh_token_hash" ~ '^[0-9a-f]{64}$'),
    ADD CONSTRAINT "auth_tokens_lifetimes" CHECK (
        "access_expires_at_utc" > "created_at_utc" AND "refresh_expires_at_utc" >= "access_expires_at_utc"
    );

CREATE FUNCTION auth_tokens_allow_only_rotation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.rotated_at_utc IS NULL AND NEW.rotated_at_utc IS NOT NULL
       AND (to_jsonb(NEW) - 'rotated_at_utc') = (to_jsonb(OLD) - 'rotated_at_utc') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'auth_tokens rows only change when their refresh token is rotated'
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER auth_tokens_rotation_only
    BEFORE UPDATE ON "auth_tokens"
    FOR EACH ROW EXECUTE FUNCTION auth_tokens_allow_only_rotation();

-- data_export_jobs: the columns that are set follow the status.
ALTER TABLE "data_export_jobs"
    ADD CONSTRAINT "data_export_jobs_status_consistent" CHECK (
        ("status" = 'pending' AND "started_at_utc" IS NULL AND "completed_at_utc" IS NULL
            AND "result" IS NULL AND "failure_code" IS NULL)
        OR ("status" = 'running' AND "started_at_utc" IS NOT NULL AND "completed_at_utc" IS NULL
            AND "result" IS NULL AND "failure_code" IS NULL)
        OR ("status" = 'completed' AND "started_at_utc" IS NOT NULL AND "completed_at_utc" IS NOT NULL
            AND "expires_at_utc" IS NOT NULL AND "result" IS NOT NULL AND "result_bytes" IS NOT NULL
            AND "failure_code" IS NULL)
        OR ("status" = 'failed' AND "completed_at_utc" IS NOT NULL AND "result" IS NULL AND "failure_code" IS NOT NULL)
        OR ("status" = 'expired' AND "completed_at_utc" IS NOT NULL AND "result" IS NULL)
    ),
    ADD CONSTRAINT "data_export_jobs_failure_code_format" CHECK (
        "failure_code" IS NULL OR "failure_code" ~ '^[a-z][a-z0-9_]{0,62}$'
    ),
    ADD CONSTRAINT "data_export_jobs_result_is_object" CHECK ("result" IS NULL OR jsonb_typeof("result") = 'object'),
    ADD CONSTRAINT "data_export_jobs_result_bytes_range" CHECK ("result_bytes" IS NULL OR "result_bytes" >= 0);

-- updated_at_utc is maintained by the database for the new tables too.
CREATE TRIGGER user_credentials_set_updated_at
    BEFORE UPDATE ON "user_credentials" FOR EACH ROW EXECUTE FUNCTION flowwave_set_updated_at();
CREATE TRIGGER auth_sessions_set_updated_at
    BEFORE UPDATE ON "auth_sessions" FOR EACH ROW EXECUTE FUNCTION flowwave_set_updated_at();
CREATE TRIGGER data_export_jobs_set_updated_at
    BEFORE UPDATE ON "data_export_jobs" FOR EACH ROW EXECUTE FUNCTION flowwave_set_updated_at();
